begin;
set local lock_timeout='5s';
lock table questions,question_keys,revision_items in share row exclusive mode;
create temporary table est_review_batch on commit drop as
select * from jsonb_to_recordset('[{"id":"0fc5cd33-336f-5d79-9847-8c3e9e40d173","status":"mathematically_verified","solution":"Factor(2a−3) from all3terms: remaining(2a+3)+(a−1)+3=3a+5. A; expanded6a²+a−15.","expected_key":"A","source_image_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{},"q_digest":"cee20a7d97f96b28c40b995092fc57e5","key_digest":"e84a99653a25b43e203bedc54bacfa48","fingerprint":"a9b7c59cd70a81f68cffd88d7b85b16b"},{"id":"10158f1b-0cf6-5f96-a001-b9107784d961","status":"repair_and_verified","solution":"Monthly multiplier2520/2400=21/20=1.05; next2520*1.05=2646; C. Original source crop checked.","expected_key":"C","source_image_checked":true,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{"stem":"The number of bees in a beehive rose from 2400 to 2520 in one month. If the population increases by the same percentage each month, how many bees are expected in the next month?","choices":[{"key":"A","text":"2600"},{"key":"B","text":"2640"},{"key":"C","text":"2646"},{"key":"D","text":"2656"}]},"q_digest":"9f03e25830319aee8d03c72d16eb1335","key_digest":"c6ffc9128531a30eed69719283f3d237","fingerprint":"b41a1baf8cdad8b7989da2729348eee9"},{"id":"11a1e605-fdee-5df7-8341-7f86e47321fd","status":"repair_and_verified","solution":"Multiply by reciprocal 2(x−3)/3; cancellation gives2(2x−3)²/[3(x−3)], x≠3; A.","expected_key":"A","source_image_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{"stem":"For x ≠ 3, simplify the square of (2x − 3)/(x − 3) divided by the fraction 3/(2x − 6).","choices":[{"key":"A","text":"2(2x − 3)²/[3(x − 3)]"},{"key":"B","text":"2(x − 3)²/[3(2x − 3)]"},{"key":"C","text":"2(2x − 3)/[3(x − 3)²]"},{"key":"D","text":"2(2x − 3)³/3"}]},"q_digest":"ffe481ea58e9eb7c743033657668af0f