mage_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{},"q_digest":"76d80f74f0770ef8e49bd807cb1c4516","key_digest":"adaee141e1a01b82e2aad4ace3043b6d","fingerprint":"03d5ed19d487906d29c90085fd0ebcb7"},{"id":"1c5532ae-a588-5192-9607-aaf78f437c83","status":"mathematically_verified","solution":"Parallelslopes3a/b=3/2 =>a/b1/2; A.","expected_key":"A","source_image_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{},"q_digest":"d89aba50831878b7c1fb1947d8fe6653","key_digest":"222638c45e0d2160d12d1e9780630aff","fingerprint":"20eafeb1eb552c3d36ba7757c3b70508"},{"id":"1c873ecc-b074-5414-b8dc-cf78a6d7f8a1","status":"repair_and_verified","solution":"Area ratio(3/1.8)²=25/9;percentlarger(25/9−1)*100=177.777%; D178%; B67π% retained from source.","expected_key":"D","source_image_checked":true,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{"stem":"Mini doughnuts have a diameter of 1.8 inches, and regular doughnuts have a diameter of 3 inches. Approximately by what percentage is the area of a regular doughnut larger than the area of a mini doughnut?","choices":[{"key":"A","text":"67%"},{"key":"B","text":"67π%"},{"key":"C","text":"78%"},{"key":"D","text":"178%"}],"explanation":"Area scales with the square of the diameter. The area ratio is (3/1.8)² = 25/9. The percent increase relative to the mini doughnut is (25/9 − 1) × 100% ≈ 177.78%, or approximately 178%."},"q_digest":"7bcf90da61fc629a3841b304a983eadb","key_digest":"343df2b09369b851780e3baf6a2cc3aa","fingerprint":"36f2df67d393c3bc2c2cbf2001d3fdf9"},{"id":"1d1852a3-a842-55a8-abf6-7bbad2cd65da","status":"mathematically_verified","solution":"LHS4x+1,RHS(2+a)x+3;nosolutionequalcoefficients a2, unequalconstants1and3; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{},"q_digest":"c00976720a9f131529b45268c182b113","key_digest":"117caec80c82b25812b4f98be4ae289b","fingerprint":"6a92c2d50ee4f8ab8ad447817e36d783"},{"id":"1dce879c-64fb-5c10-8d79-5892cb9b7602","status":"mathematically_verified","solution":"Group4x²(x+2)+(x+2)=(x+2)(4x²+1); exactlyonerealroot−2; B.","expected_key":"B","source_image_checked":false,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{},"q_digest":"ceb449bf79195a9880e33f9bff16a746","key_digest":"95952c0731cf665ac208214e22065eee","fingerprint":"f731f0aedac566371bcea9d96ac44cda"},{"id":"1eab2836-30b8-57b6-8496-b9cd04665db8","status":"repair_and_verified","solution":"Slope(19−7)/(8−2)=2;intercept3;a11;b5;ab55; D. Table source checked.","expected_key":"D","source_image_checked":true,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{"stem":"The pairs (x, y) in the table are (2, 7), (4, a), (b, 13), and (8, 19). They form a linear relationship. What is the value of ab?","image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/fa-049-1.png"},"q_digest":"5922b4b94740037b73dab19846bd5dcd","key_digest":"a822881668ec1cf9ae40997c363dc588","fingerprint":"20d19c4ad5e00551374bf14e5f4c9b3b"},{"id":"1ebaae07-19c0-5d8f-a4eb-eb9ac17bc25c","status":"repair_and_verified","solution":"Source weekend−weekday:TV4,heater3,lights2,computer−4,washer2,fridge0,others2;B.","expected_key":"B","source_image_checked":true,"scope":"Current complete stem, choices and independent worked solution; attached source images checked where required","repair":{"image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-062-1.png"},"q_digest":"b1b2afe76a46e55e58b44502e514aae9","key_digest":"69bf7a27c66754ffe7f51552f0827b61","fingerprint":"ae28d0664d45b4540bbd0d7e10f2e45a"}]'::jsonb)
as t(id uuid,status text,solution text,expected_key text,source_image_checked boolean,scope text,repair jsonb,q_digest text,key_digest text,fingerprint text,old_stem text);
do $$ begin
if exists(select 1 from audit_log where action='questions.est_remaining_batch02.20260930') then raise exception 'Batch already applied'; end if;
if (select count(*) from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id where q.track_id='est' and md5(to_jsonb(q)::text)=t.q_digest and md5(to_jsonb(k)::text)=t.key_digest and k.correct#>>'{}'=t.expected_key and nullif(q.assets->>'release_hold_reason','') is null)<>25 then raise exception 'Reviewed question version changed'; end if;
end $$;
create temporary table est_review_revision_before on commit drop as
select r.question_id,r.active,r.fingerprint=t.fingerprint was_ready
from revision_items r join est_review_batch t on t.id=r.question_id;
insert into audit_log(action,target_type,target_id,meta)
select 'questions.est_remaining_batch02.20260930','question',q.id::text,
jsonb_build_object('previous_stem',q.stem,'previous_choices',q.choices,'previous_assets',q.assets,'previous_explanation',k.explanation,'solution',t.solution,'scope',t.scope,'source_image_checked',t.source_image_checked,'status',t.status)
from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id;
update questions q set
stem=coalesce(t.repair->>'stem',q.stem),
choices=coalesce(t.repair->'choices',q.choices),
assets=q.assets||jsonb_build_object('answer_review','2026-09-30-independent-current-stem-review','mathematical_review_scope',t.scope)||
case when t.repair ? 'image' then jsonb_build_object('image',t.repair->>'image') else '{}'::jsonb end
from est_review_batch t where q.id=t.id;
update question_keys k set explanation=t.repair->>'explanation'
from est_review_batch t where k.question_id=t.id and t.repair ? 'explanation';
update revision_items r set fingerprint=revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)
from questions q join question_keys k on k.question_id=q.id join est_review_revision_before b on b.question_id=q.id
where r.question_id=q.id and b.was_ready;
do $$ begin
if exists(select 1 from est_review_revision_before b join revision_items r using(question_id) where r.active is distinct from b.active) then raise exception 'Release status changed'; end if;
if (select count(*) from audit_log where action='questions.est_remaining_batch02.20260930')<>25 then raise exception 'Audit incomplete'; end if;
end $$;
commit;
